			const admin_page_path = window.location.pathname;
			const masking_page_reg = /.*(applicant_list|qna_list)\.asp/g;
			!admin_page_path.search(masking_page_reg) && createLoadingLayout();

			function createLoadingLayout(){
				const loadingLayout = document.createElement("div");
				const loadingSpinner = document.createElement("div");
				const html = document.querySelector("html");
				const scroll = sessionStorage.getItem("scroll") || 0;

				html.style.overflow = 'hidden'
				loadingLayout.className = "loadingWrap";
				loadingSpinner.className = "loadingSpinner";
				loadingLayout.style.cssText = `
					display: flex;
					justify-content: center;
					align-items: center;
					position: absolute;
					top: ${scroll}px;
					left: 0%;
					background-color: #ededed;
					width: 100%;
					height: 180vh;
					z-index: 1001;
					opacity: 0.93;
					`;
				loadingSpinner.style.cssText = `
					width: 80px;
					height: 80px;
					border: 6px solid #3498db;
					border-top: 5px solid transparent;
					border-radius: 50%;
					animation: rotate 0.6s linear infinite;
				`
				document.querySelector("html").append(loadingLayout);
				document.querySelector(".loadingWrap").append(loadingSpinner);
			};

